# Parse JSONL to extract demo grids properly
def parse_grids_from_session(filepath):
    with open(filepath, 'r') as f:
        lines = f.readlines()

    grids = {}
    current_header = None

    for line in lines:
        try:
            msg = json.loads(line)
            if 'message' not in msg:
                continue
            content_list = msg['message'].get('content', [])
            for item in content_list:
                if item.get('type') == 'text':
                    text = item.get('text', '')

                    # Look for grid data
                    lines = text.split('\n')
                    for ln in lines:
                        ln = ln.strip()
                        if ln and re.match(r'^\d+\s+(?:\d+\s+)*\d+\s+$', ln):
                            if current_header and current_header not in grids:
                                grids[current_header] = []
                            grids[current_header].append([int(x) for x in ln.split()])

                        # Look for header
                        m = re.match(r'Demo pair (\d+) (input|output) \((\d+)x(\d+)\):', ln)
                        if m:
                            pair_num, ptype, h, w = m.groups()
                            if ptype == 'input':
                                current_header = f"Demo pair {pair_num} input ({h}x{w})"
                            elif ptype == 'output' and pair_num is not None:
                                current_header = f"Demo pair {pair_num} output ({h}x{w})"
        except:
            continue

    return grids

